fn test_logistic_monotone() -> bool with IO, Mut, Panic, Div {
    let dt = 20.0 / 2000.0
    SCAL_W.u = 0.1
    SCAL_W.t = 0.0
    var prev_u = SCAL_W.u
    var i = 0
    var monotone = true
    while i < 2000 {
        rk4_step_logistic(dt)
        if SCAL_W.u < prev_u {
            monotone = false
        }
        prev_u = SCAL_W.u
        i = i + 1
    }
    return monotone
}

