        var j = i + 1
        while j < m {
            sum = sum - M_d[i * m + j] * c_vec[j]
            j = j + 1
        }
        let diag = M_d[i * m + i]
        if mr_abs(diag) > 1.0e-30 {
            c_vec[i] = sum / diag
        } else {
            c_vec[i] = 0.0
        }
        if i == 0 { done_bs = true } else { i = i - 1 }
    }

    i = 0
    while i < nd {
        var sum = 0.0
        var j = 0
        while j < m {
            sum = sum + deim.U[i * m + j] * c_vec[j]
            j = j + 1
        }
        f_approx[i] = sum
        i = i + 1
    }
    return f_approx
}

// ============================================================================
// DIRECT FULL-SYSTEM SOLVE (Gaussian elimination for tests)
// ============================================================================

fn direct_solve(A: &[f64; 4096], b: &[f64; 256], n: i32,
                x: &![f64; 256]) with Mut, Div, Panic {
    var M: [f64; 4096] = [0.0; 4096]
    var rhs: [f64; 256] = [0.0; 256]
    var i = 0
    while i < n {
        var j = 0
        while j < n {
            M[i * n + j] = A[i * n + j]
            j = j + 1
        }
        rhs[i] = b[i]
        i = i + 1
    }

    var col = 0
    while col < n {
        var pivot_row = col
        var pivot_val = mr_abs(M[col * n + col])
        var row = col + 1
        while row < n {
            let v = mr_abs(M[row * n + col])
            if v > pivot_val { pivot_val = v; pivot_row = row }
            row = row + 1
        }
        if pivot_row != col {
            var k = 0
            while k < n {
                let tmp = M[col * n + k]
                M[col * n + k] = M[pivot_row * n + k]
                M[pivot_row * n + k] = tmp
                k = k + 1
            }
            let tmp_r = rhs[col]
            rhs[col] = rhs[pivot_row]
            rhs[pivot_row] = tmp_r
        }
        let diag = M[col * n + col]
        if mr_abs(diag) > 1.0e-30 {
            row = col + 1
            while row < n {
                let factor = M[row * n + col] / diag
                var k = col + 1
                while k < n {
                    M[row * n + k] = M[row * n + k] - factor * M[col * n + k]
                    k = k + 1
                }
                M[row * n + col] = 0.0
                rhs[row] = rhs[row] - factor * rhs[col]
                row = row + 1
            }
        }
        col = col + 1
    }

    i = n - 1
    var done_back = false
    while i >= 0 && done_back == false {
        var sum = rhs[i]
        var j = i + 1
        while j < n {
            sum = sum - M[i * n + j] * x[j]
            j = j + 1
        }
        let diag = M[i * n + i]
        if mr_abs(diag) < 1.0e-30 {
            x[i] = 0.0
        } else {
            x[i] = sum / diag
        }
        if i == 0 { done_back = true } else { i = i - 1 }
    }
}

